WITH filtered AS (SELECT id, customer_id, device, browser, started_at, country, CASE WHEN country = 'TH' THEN 1 ELSE 0 END AS is_th, UPPER(country) AS country_upper FROM sessions WHERE started_at > DATE '2023-08-18' AND country IN ('US', 'SG')), with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT customer_id, SUM(new_group_flag) AS total_new_group_flag, COUNT(DISTINCT device) AS distinct_devices, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count FROM sessionized GROUP BY 1 ORDER BY edge_count DESC
